    "testo": "{\"p\":{\"ins\":{\"#text\":\"((ARTICOLO ABROGATO DALLA L. 19 MAGGIO 1975, N. 151))\",\"@_eId\":\"ins_227\"},\"#text\":\"Art. 220.\"}}"
